package com.prudence.monitoring;
import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/monitoring/capas") public class CapaController {private final CapaRepository repo; private final MonitoringSignalRepository signals; public CapaController(CapaRepository r,MonitoringSignalRepository s){repo=r;signals=s;} @PostMapping public CapaJpaEntity open(@RequestBody Open b){var signal=signals.findById(b.signalId).orElseThrow(()->new IllegalArgumentException("signal not found"));return repo.save(new CapaJpaEntity(UUID.randomUUID().toString(),signal.getAiSystemId(),signal.getId(),b.risk,b.mitigation,b.owner,b.dueAt));} @PostMapping("/{id}/implement") public CapaJpaEntity implement(@PathVariable String id){var c=repo.findById(id).orElseThrow();c.implement();return repo.save(c);} @PostMapping("/{id}/verify") public CapaJpaEntity verify(@PathVariable String id,@RequestBody Verify b){var c=repo.findById(id).orElseThrow();c.verify(b.evidenceReference);return repo.save(c);} public record Open(String signalId,String risk,String mitigation,String owner,String dueAt){} public record Verify(String evidenceReference){} }
